// S9-8d: the host's own browser tier — does `Files made from your invitation` actually deliver bytes?
//
// Everything before this instrument proved the publisher's half: a row exists, its digest matches the
// object in the private bucket, and the HTTP battery refuses the wrong caller. This one proves the
// sentence the mandate asks for — *an authenticated host, in the shipped product, lists their completed
// outputs, presses for a link, and gets the exact generated bytes back* — and that another wedding's
// owner and an anonymous visitor get nothing. It drives the bundle in `dist/` over `vite preview`, the
// app's own sign-in and editor routes, and the panel as it ships; no component is mounted or stubbed.
//
// Why the fixture is an already-published wedding rather than one this run creates.
//   The artefacts under test are the trusted publisher's output (`scripts/stage9-output-publisher.mjs`
//   over `scripts/stage9-render-worker.mjs`, the only renderer in the repo), and re-drawing them here
//   would either need a second publisher or mutate a census this tier is meant to read. The wedding
//   named by `--fixture` is the one that chain already delivered: `publish-4.txt` records its eight
//   artefacts ending `ready`. What this run does add is a *second* host, made through the shipped
//   `/signup` form and owning a *second* wedding, because "another wedding's owner" has to be a real
//   owner rather than an assumption — and both are torn down at the end.
//
// How the privileged credential stays out of the browser.
//   The service-role key in `.env.local` is used by this Node process only, for two things: reading the
//   census (manifest rows and the `weddings` count) and deleting the fixture this run made. Every
//   assertion about *access* is made either by a browser page or with that page's own bearer token
//   through `page.authHeader()`, so a refusal on the wire is the product's refusal, not a maintenance
//   role declining to answer. `makeRedactor()` covers both keys and both host passwords, so no line this
//   file prints or records can carry a credential; the run record goes to the evidence directory,
//   outside the repository.
//
// What this tier does NOT measure, stated because the panel's own header comment claims it.
//   The reprint warnings for a retired artefact (`token_rotated`, `publication_revoked`, `superseded`)
//   need an `invalidated` row. The maintenance role can reach that state over HTTP — `ready → invalidated`
//   is a legal edge (migration `:345`) and `service_role` bypasses RLS — but `invalidated` is terminal
//   (`:332-333`), so retiring a row here would permanently retire the only eight artefacts this tier reads
//   and every later run would find a manifest with nothing to deliver. Drawing a throwaway row to retire
//   instead means a full register → upload → ready → invalidate → delete cycle, which is the publisher's
//   job, not a browser tier's. So H-06 measures the branch that this manifest can show — no retirement
//   sentence while nothing is invalidated, and the QR-limit sentence exactly when a ready plate exists —
//   and says which half it did not reach. The retired-row sentences themselves are pinned by
//   `src/test/invitationOutputs.test.ts`; that is a unit-tier fact, not a browser-tier one.
//   Real hosted Open Graph preview (a crawler fetching a public `/i/…` page from the deployed origin) is
//   likewise not measured here: this run has one origin, loopback, and no crawler.
//
// Usage:
//   node scripts/stage9-browser-outputs.mjs --fixture ../q9-logs/live/ids.json \
//     --host-password-env VIVAAHVARNAM_S9_HOST_PASSWORD
// Options: `--api <origin>`, `--preview <origin>` (both defaulted, both must be loopback),
//   `--cdp-port <n>`, `--evidence <dir>`, `--keep-second-host` (skip the second host's teardown while
//   debugging a failure). Exit 0 every check passed, 1 a check failed, 2 the run could not start.
//
// Cases: PRELUDE P-01..03 · HOST-LIST H-01..06 · DELIVERY D-P01, one D-<kind>-<variant>-<format>-p<n>
// per artefact, D-TTL-01..03, D-HY-01..02 · REFUSAL R-A1..A5, R-B1..B5, R-X1 · A11Y A-01..07 ·
// MOBILE M-01..02 · NETWORK N-01..03 · TEARDOWN T-01..05.

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { assertLoopback, openBrowser } from './stage5-browser-driver.mjs';
import { outputDeliveryPath } from '../src/lib/invitationOutputs.ts';

const ROOT = resolve(import.meta.dirname, '..');
const LOOPBACK = new Set(['127.0.0.1', 'localhost', '::1']);
const sleep = (ms) => new Promise((done) => setTimeout(done, ms));
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

class Refusal extends Error {
  constructor(message, exitCode = 2) { super(message); this.exitCode = exitCode; }
}

/** The prefix of every address this tier signs up, and the only thing teardown matches on. A product
 *  fixture from an earlier tier can never be named by it. */
const HOST_B_PREFIX = 's9-delivery-host-b';

/** The private artefact bucket, named by the product at
 *  `src/integrations/supabase/invitationOutputs.ts:49`, where the constant is module-private. Storage's
 *  signed and authenticated read addresses both take the form `/{bucket}/{object_key}`, so an
 *  instrument that leaves the bucket out gets refused for a malformed address rather than by a policy —
 *  and would report that refusal as a security pass. */
const OUTPUT_BUCKET = 'invitation-outputs';

// ------------------------------------------------------------------------ options

const BOOLEAN_FLAGS = new Set(['keep-second-host']);

// Same shape as scripts/stage9-output-publisher.mjs: a bare --flag is boolean, and
// `--name value` carries its value in the next token. A parser that only understands
// `--name=value` silently turns `--host-password-env NAME` into the literal string
// "true" and the run refuses for the wrong reason.
function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token.startsWith('--')) continue;
    const body = token.slice(2);
    const eq = body.indexOf('=');
    if (eq !== -1) {
      out[body.slice(0, eq)] = body.slice(eq + 1);
      continue;
    }
    if (BOOLEAN_FLAGS.has(body)) {
      out[body] = true;
      continue;
    }
    const next = argv[i + 1];
    if (next === undefined || next.startsWith('--')) out[body] = true;
    else {
      out[body] = next;
      i += 1;
    }
  }
  return out;
}

function localEnv(path) {
  if (!existsSync(path)) return {};
  const out = {};
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    if (line.trim().startsWith('#') || !line.includes('=')) continue;
    const i = line.indexOf('=');
    out[line.slice(0, i).trim()] = line.slice(i + 1).trim().replace(/^"|"$/g, '');
  }
  return out;
}

export function readOptions(args, env) {
  const fixturePath = resolve(String(args.fixture ?? join(ROOT, '..', 'q9-logs', 'live', 'ids.json')));
  const passwordEnv = String(args['host-password-env'] ?? '');
  if (passwordEnv === '') {
    throw new Refusal('refused: --host-password-env <NAME> is required. The fixture host\'s local '
      + 'password is a credential like any other, and argv is not a credential store.');
  }
  const hostAPassword = String(env[passwordEnv] ?? '');
  if (hostAPassword === '') throw new Refusal(`refused: ${passwordEnv} is not set, so the host cannot sign in.`);
  if (!existsSync(fixturePath)) throw new Refusal(`refused: no fixture at ${fixturePath}.`);

  const fileEnv = localEnv(resolve(ROOT, '.env.local'));
  const serviceKey = fileEnv.SUPABASE_LOCAL_SERVICE_ROLE_KEY;
  const anonKey = fileEnv.SUPABASE_LOCAL_PUBLISHABLE_KEY;
  if (typeof serviceKey !== 'string' || serviceKey === '') {
    throw new Refusal('refused: .env.local carries no service-role key, and this tier reads its census '
      + 'and performs its teardown with it. It has no other way to address the private bucket.');
  }
  let api;
  let preview;
  try {
    api = assertLoopback(String(args.api ?? fileEnv.SUPABASE_LOCAL_URL), 'the API origin');
    preview = assertLoopback(String(args.preview ?? 'http://127.0.0.1:4173'), 'the render origin');
  } catch (error) {
    throw new Refusal(`refused: ${error.message}`);
  }
  const tag = `s9d-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  return {
    fixturePath, api, preview, serviceKey, anonKey, hostAPassword,
    hostBTag: tag,
    cdpPort: args['cdp-port'] === undefined ? 9419 : Number(String(args['cdp-port'])),
    evidenceDir: resolve(String(args.evidence ?? join(ROOT, '..', 'q9-logs'))),
    keepSecondHost: Boolean(args['keep-second-host']),
  };
}

/** Every credential this run can see, applied to every line it prints or records. A service-role key
 *  reaching a log is the failure mode the whole stage exists to avoid, so masking happens before
 *  anything can hold the string, not on the way out of an error handler. */
export function makeRedactor(secrets) {
  const known = secrets.filter((s) => typeof s === 'string' && s.length >= 8);
  return (text) => known.reduce((acc, secret) => acc.split(secret).join('<redacted>'), String(text));
}

// ------------------------------------------------------------------------ the maintenance channel

/** The service-role HTTP door — census reads and this run's own teardown only. Never handed to a page. */
function makeMaintenance({ api, serviceKey, anonKey }) {
  const call = async (path, { method = 'GET', body, headers = {} } = {}) => {
    const res = await fetch(`${api}${path}`, {
      method,
      headers: {
        apikey: anonKey,
        Authorization: `Bearer ${serviceKey}`,
        ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
        ...headers,
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const text = await res.text();
    let json = null;
    try { json = text === '' ? null : JSON.parse(text); } catch { json = { unparsed: text.slice(0, 200) }; }
    return { status: res.status, json, text };
  };
  return {
    call,
    rows: async (path) => {
      const r = await call(path);
      if (!Array.isArray(r.json)) {
        throw new Refusal(`refused: the census read ${path} answered ${r.status}, not a row list: `
          + `${r.text.slice(0, 160)}`);
      }
      return r.json;
    },
  };
}

// ------------------------------------------------------------------------ the panel's DOM, read as data

/** Marks each artefact row with the fingerprint it renders, so a press can be aimed at one row and the
 *  on-screen list can be compared with the database's own rows by a value the host actually reads.
 *  Marking the DOM is the posture the Stage 5 and 6 drivers already take (`data-stage5-press`). It is
 *  re-run before every aim, because a re-render may hand back a fresh node and a harness aiming at a
 *  stale marker would report "no such button" as a product verdict. */
const MARK_ROWS = `(() => {
  const section = document.querySelector('section[aria-labelledby="outputs-heading"]');
  if (!section) return null;
  // The reprint notices are also <li> elements (InvitationOutputsPanel.tsx:202-211), so a bare
  // section-wide li query counts one row that is not an artefact. Artefact rows are the li of a
  // group list; a notice sits inside the role=status list instead.
  const rows = [...section.querySelectorAll('li')].filter((li) => li.closest('[role="status"]') === null);
  rows.forEach((li) => { delete li.dataset.s9row; });
  return rows.map((li) => {
    const mono = li.querySelector('span.font-mono');
    const fingerprint = mono ? mono.textContent.trim() : '';
    const summary = li.querySelector('p')?.textContent.trim().replace(/\\s+/g, ' ') ?? '';
    if (!/^[0-9a-f]{12}$/.test(fingerprint)) return { fingerprint: null, summary };
    li.dataset.s9row = fingerprint;
    return { fingerprint, summary };
  });
})()`;

/** Every actionable control inside the panel, with the box the browser gave it, the name it announces
 *  and whether the keyboard can stop on it. One expression serves A-01, A-02, A-06 and M-02, because all
 *  four ask the same question of the same elements and a case that re-found them independently would
 *  measure a different render of the page. */
const PANEL_CONTROLS = `(() => {
  const section = document.querySelector('section[aria-labelledby="outputs-heading"]');
  if (!section) return null;
  return [...section.querySelectorAll('button,a[href]')].map((el) => {
    const r = el.getBoundingClientRect();
    const name = (el.getAttribute('aria-label') || el.textContent || '').trim().replace(/\\s+/g, ' ');
    return {
      tag: el.tagName, name,
      width: Math.round(r.width * 10) / 10, height: Math.round(r.height * 10) / 10,
      disabled: Boolean(el.disabled), tabbable: Number(el.tabIndex) >= 0,
    };
  });
})()`;

/** Text colour against the first opaque background above it — the pair a WCAG contrast claim needs.
 *  Computed in the page, where the cascade has already resolved; a Node-side guess about the design
 *  tokens would be a claim about CSS rather than a measurement of this render. */
const CONTRAST_MATH = `
  const parse = (value) => {
    const m = /rgba?\\(([\\d.]+),\\s*([\\d.]+),\\s*([\\d.]+)(?:,\\s*([\\d.]+))?\\)/.exec(value);
    return m ? { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] } : null;
  };
  const luminance = ({ r, g, b }) => {
    const f = (v) => { const s = v / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const backgroundOf = (el) => {
    for (let node = el; node; node = node.parentElement) {
      const colour = parse(getComputedStyle(node).backgroundColor);
      if (colour && colour.a >= 0.99) return colour;
    }
    return { r: 255, g: 255, b: 255, a: 1 };
  };
  const runOf = (node) => {
    const text = node.textContent.trim();
    if (text.length < 3) return null;
    const el = node.parentElement;
    if (!el) return null;
    const box = el.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return null;
    const cs = getComputedStyle(el);
    const fg = parse(cs.color);
    if (!fg || fg.a < 0.99) return null;
    const bg = backgroundOf(el);
    const l1 = luminance(fg), l2 = luminance(bg);
    const ratio = (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
    const size = parseFloat(cs.fontSize);
    const large = size >= 24 || (size >= 18.66 && (cs.fontWeight === 'bold' || +cs.fontWeight >= 700));
    return { text: text.slice(0, 40), size, large, ratio: Math.round(ratio * 100) / 100,
      required: large ? 3 : 4.5 };
  };
`;

/** Every visible text run inside the panel, measured against the surface it is actually drawn on. */
const PANEL_CONTRAST = `(() => {
  const section = document.querySelector('section[aria-labelledby="outputs-heading"]');
  if (!section) return null;
  ${CONTRAST_MATH}
  const out = [];
  const walker = document.createTreeWalker(section, window.NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const run = runOf(node);
    if (run !== null) out.push(run);
  }
  return out;
})()`;

/** The same math over every `.text-warning` run on the page, minus the embedded guest document.
 *
 *  `--warning` is one shared token, and eight sites paint with it (`AuthoringOutline.tsx:140`,
 *  `TraditionPackPanel.tsx:289`, `ShareQrPlate.tsx:95`, `PublicationPanel.tsx:101,166,326`,
 *  `GuestInvitationPanel.tsx:648`, `InvitationOutputsPanel.tsx:206`), so an A-04 pass alone would observe
 *  one of them. The token is what the repair went into, so the sweep covers the blast radius on the same
 *  render rather than trusting the arithmetic in `src/index.css`. */
const WARNING_CONTRAST = `(() => {
  ${CONTRAST_MATH}
  const inPreview = (el) => el.closest('[aria-labelledby="preview-heading"],[aria-label="Preview"]') !== null;
  const panelOf = (el) => {
    const region = el.closest('section[aria-labelledby],aside[aria-labelledby]');
    const head = region ? region.querySelector('h1,h2,h3,h4') : null;
    return (head ? head.textContent : el.tagName).trim().replace(/\\s+/g, ' ').slice(0, 40);
  };
  const out = [];
  for (const host of [...document.querySelectorAll('.text-warning')].filter((el) => !inPreview(el))) {
    const walker = document.createTreeWalker(host, window.NodeFilter.SHOW_TEXT);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      const run = runOf(node);
      if (run !== null) out.push(Object.assign(run, { label: panelOf(host) }));
    }
  }
  return out;
})()`;

/** The manifest call the *app* made, copied rather than invented.
 *
 *  The panel reaches `api.list_invitation_outputs` through a schema-qualified PostgREST call, and the
 *  address and profile header that call carries are the product's business. A harness that writes its
 *  own `/rest/v1/rpc/list_invitation_outputs` gets PGRST202 "Searched for the function
 *  public.list_invitation_outputs" — a refusal about the harness's spelling, which an assert on
 *  `status !== 200` would happily score as a privacy pass. So the URL and `Content-Profile` are read
 *  back from the captured traffic and replayed with somebody else's credentials.
 *
 *  The header *names* are matched case-insensitively for the reason the driver gives at its own
 *  `rpcHeaders()`: Chrome hands back whatever spelling the sender used. */
async function discoverManifestCall(page) {
  const log = await page.networkLog();
  const hit = log.filter((entry) => /\/rest\/v1\/rpc\/[^?]*invitation_outputs/.test(entry.url)).at(-1);
  if (hit === undefined) {
    throw new Refusal('refused: the panel never made a manifest call this run can see, so there is no '
      + 'app-shaped address to replay. A hand-written one measures the harness, not the policy.');
  }
  const headers = { ...(hit.headers ?? {}), ...(hit.sentHeaders ?? {}) };
  const profileKey = Object.keys(headers).find((k) => k.toLowerCase() === 'content-profile');
  return { url: hit.url, profile: profileKey === undefined ? null : headers[profileKey] };
}

/** True when a refusal is about the caller rather than about an address that names nothing.
 *
 *  The two families this run recorded behave differently, and the difference is the whole point.
 *  `NoSuchBucket`/`Bucket not found` and PostgREST's `PGRST202 "Searched for the function…"` mean the
 *  *address* matched no object or no function, which is true for everybody including the owner, so a
 *  `status !== 200` on such an address is a measurement of the harness's spelling. `NoSuchKey`
 *  "Object not found" is something else: recorded here for both an anonymous session and a second
 *  host on the exact key the fixture owner downloads bytes from in the same run. Storage's
 *  `storage.objects` policies make a foreign object absent rather than forbidden, and that invisibility
 *  is the privacy property this tier is claiming — so it passes this filter, with the owner's own
 *  successful download (every D- case, plus R-X1 immediately after) as the control that the object
 *  exists. R-A5 is the one exception: its public route answers `NoSuchBucket` *because* the bucket is
 *  private, which is the claim, so that case does not run this filter. */
const refusalResolves = (text) => !['NoSuchBucket', 'Bucket not found', 'PGRST202',
  'Searched for the function'].some((marker) => text.includes(marker));

const MAGIC = {
  png: [Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])],
  webp: [(b) => b.subarray(0, 4).toString('latin1') === 'RIFF' && b.subarray(8, 12).toString('latin1') === 'WEBP'],
  pdf: [(b) => b.subarray(0, 5).toString('latin1') === '%PDF-'],
};

/** The token's own expiry claim, if it carries one. Storage answers a signed URL whose token is a
 *  base64url document with `exp` inside; the spelling has varied across builds, so both the `expires`
 *  parameter and any decodable JSON segment are tried, and null is returned rather than a number
 *  invented. D-TTL-02 does not depend on it — the empirical wait is the authority. */
export function expiryOf(signedUrl) {
  let url;
  try { url = new URL(signedUrl); } catch { return null; }
  const expires = url.searchParams.get('expires');
  if (expires !== null && /^\d+$/.test(expires)) {
    const seconds = Number(expires);
    return { expMs: seconds > 1e11 ? seconds : seconds * 1000, source: 'expires parameter' };
  }
  const token = url.searchParams.get('token');
  if (token === null) return null;
  for (const part of decodeURIComponent(token).split(/[.~]/)) {
    try {
      const json = JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
      if (typeof json.exp === 'number') return { expMs: json.exp * 1000, source: 'token payload' };
    } catch { /* not a JSON segment; the next one may be */ }
  }
  return null;
}

const download = async (href) => {
  const res = await fetch(href);
  const buffer = Buffer.from(await res.arrayBuffer());
  return { status: res.status, buffer, bytes: buffer.length, contentType: res.headers.get('content-type') };
};

/** A manifest row as the database spells it, put through the client's own path builder. The builder
 *  takes the projection's camelCase fields, so this is the composition test the lib header promises:
 *  `outputDeliveryPath` must agree with the key `private.mint_invitation_output_key()` wrote, or a
 *  drifted template would surface here as a download that cannot work. */
const composedPath = (weddingId, row) => outputDeliveryPath(weddingId, {
  id: row.id, kind: row.output_kind, variant: row.variant, format: row.format,
  pageNumber: row.page_number, status: row.status, storageDomain: row.storage_domain,
  contentDigest: row.content_digest, renderConfigHash: row.render_config_hash,
  versionId: row.version_id, readyAt: null, invalidationReason: null, attemptCount: row.attempt_count,
  lastError: null, createdAt: row.created_at,
});

// ------------------------------------------------------------------------ the browser side

/** Types into a form and submits it, reading each value back before pressing. The behaviour is copied
 *  from `scripts/stage8-browser-guest.mjs:fillAndSubmit`: the app's inputs are controlled, so a value
 *  that did not stick means the form was mid-render, not that the product refused. */
async function fillAndSubmit(page, fields, buttonWords) {
  for (let attempt = 1; attempt <= 8; attempt += 1) {
    if (await page.waitForSelector(Object.keys(fields)[0], 8_000)) {
      const missing = [];
      for (const [selector, value] of Object.entries(fields)) {
        await page.setBySelector(selector, value);
        const readBack = await page.evaluate(
          `document.querySelector(${JSON.stringify(selector)})?.value ?? null`);
        if (readBack !== value) missing.push(selector);
      }
      if (missing.length === 0) return page.pressButton(buttonWords);
      if (attempt === 8) throw new Error(`the form would not hold its values: ${missing.join(', ')}`);
    }
    await sleep(300);
  }
  return 'absent';
}

async function waitForUrl(page, part, timeoutMs = 20_000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const url = await page.currentUrl();
    if (url.includes(part)) return url;
    if (Date.now() > deadline) return null;
    await sleep(200);
  }
}

async function signInHost(page, preview, { email, password, label }) {
  await page.goto(`${preview}/login`);
  const pressed = await fillAndSubmit(page, { '#email': email, '#password': password }, 'Log in');
  const url = await waitForUrl(page, '/dashboard');
  if (url === null) {
    throw new Refusal(`${label} could not reach the dashboard (press answered ${pressed}; page said: `
      + `${(await page.bodyText()).replace(/\s+/g, ' ').slice(0, 200)})`, 2);
  }
  return url;
}

/** The second host, made the way a host is made: the shipped sign-up form, then the shipped create
 *  flow. Each writes exactly one row — an `auth.users` entry and a `weddings` entry — which is what
 *  makes teardown provable. No draft is saved, because `invitation_versions.wedding_id` is
 *  `ON DELETE NO ACTION` (`supabase/migrations/20260925120200_stage2_versions_and_publication.sql:21`),
 *  so a version row would make this fixture undeletable without a database session. */
async function signUpSecondHost(browser, preview, { email, password, weddingTitle }) {
  const page = await browser.newPage('host-b');
  await page.goto(`${preview}/signup`);
  await page.waitForSelector('form');
  const signed = await fillAndSubmit(page, {
    '#name': 'Second Host', '#email': email, '#password': password,
  }, 'Sign up');
  if (signed !== 'pressed') throw new Refusal(`refused: the sign-up button was not pressable (${signed}).`, 2);
  await waitForUrl(page, '/login');
  const logged = await fillAndSubmit(page, { '#email': email, '#password': password }, 'Log in');
  if (await waitForUrl(page, '/dashboard') === null) {
    throw new Refusal(`refused: the second host never reached a dashboard (press answered ${logged}; `
      + `${(await page.bodyText()).replace(/\s+/g, ' ').slice(0, 200)})`, 2);
  }
  await page.clickLink('Create Invitation');
  await page.waitForSelector('#title');
  const created = await fillAndSubmit(page, { '#title': weddingTitle, '#language': 'en' }, 'Create Invitation Draft');
  const url = await waitForUrl(page, '/project/');
  const weddingId = url === null ? null : /\/project\/([0-9a-f-]{36})/.exec(url)?.[1];
  if (!weddingId || !UUID.test(weddingId)) {
    throw new Refusal(`refused: the second wedding was never formed (press answered ${created}; `
      + `url ${url ?? 'none'})`, 2);
  }
  return { page, weddingId };
}

/** Opens the editor for one wedding and returns its rows as the page renders them. */
async function openPanel(page, preview, weddingId) {
  await page.goto(`${preview}/project/${weddingId}/edit`);
  if (!(await page.waitForSelector('section[aria-labelledby="outputs-heading"]', 20_000))) {
    throw new Refusal(`refused: the panel never mounted at /project/${weddingId}/edit — page said: `
      + `${(await page.bodyText()).replace(/\s+/g, ' ').slice(0, 220)}`, 2);
  }
  // The section mounts before its manifest read has answered, so for a moment the list is legitimately
  // empty — which is how the last run came back with "0 fingerprint(s)" beside a tally that said eight.
  // The panel's own in-flight signal is the Refresh button, disabled while `busy` is true
  // (InvitationOutputsPanel.tsx:180-186), so waiting for it to re-enable is waiting for the product's
  // stated condition rather than sleeping, and it cannot retry away a real refusal: a read that ends in
  // an error leaves the button enabled and the row count whatever the product decided to show.
  const deadline = Date.now() + 25_000;
  for (;;) {
    const idle = await page.evaluate(`(() => {
      const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
      if (!s) return null;
      const refresh = [...s.querySelectorAll('button')]
        .find((b) => (b.textContent || '').trim() === 'Refresh');
      return refresh ? refresh.disabled === false : 'no-refresh-button';
    })()`);
    if (idle === true) break;
    if (Date.now() > deadline) {
      throw new Refusal(`refused: the panel never finished its manifest read — Refresh stayed in state `
        + `${JSON.stringify(idle)} for 25 s, so there is no settled list to measure.`, 2);
    }
    await sleep(150);
  }
  return page.evaluate(MARK_ROWS);
}

/** Presses one row's button and reads the address the panel hands out. `absent` and `disabled` are the
 *  product's verdicts and are reported as such rather than retried away. */
async function pressForRow(page, fingerprint) {
  if (fingerprint === '' || fingerprint === undefined) return { pressed: 'no fingerprint', href: null };
  await page.evaluate(MARK_ROWS);
  const scope = `li[data-s9row="${fingerprint}"]`;
  let pressed;
  try {
    pressed = await page.pressButtonWhenReady('Get a temporary link', 25_000, scope);
  } catch (error) {
    return { pressed: `threw: ${String(error.message).slice(0, 80)}`, href: null };
  }
  if (pressed !== 'pressed') return { pressed, href: null };
  const deadline = Date.now() + 15_000;
  for (;;) {
    const href = await page.evaluate(`(() => {
      const li = document.querySelector(${JSON.stringify(scope)});
      const a = li ? [...li.querySelectorAll('a[href]')].find((x) => x.textContent.includes('Open the file')) : null;
      return a ? a.getAttribute('href') : null;
    })()`);
    if (typeof href === 'string' && href !== '') return { pressed, href };
    if (Date.now() > deadline) {
      const said = await page.evaluate(`(() => {
        const li = document.querySelector(${JSON.stringify(scope)});
        return li ? li.innerText.replace(/\\s+/g, ' ').slice(0, 200) : null;
      })()`);
      return { pressed, href: null, said };
    }
    await sleep(200);
  }
}

/** Re-reads the panel, then presses one row's affordance.
 *
 *  `links` is component state (InvitationOutputsPanel.tsx:111), so a row that has already been pressed
 *  shows its anchor and no longer offers the button. Re-pressing without a re-read would report
 *  "no such button" as if the product had refused a second link — whereas the product's promise is that
 *  an address is minted per press and dropped on the next read. A remount is how a host gets there. */
async function pressAfterRemount(page, preview, weddingId, fingerprint) {
  await page.goto(`${preview}/project/${weddingId}/edit`);
  const rows = await openPanel(page, preview, weddingId);
  if (rows === null) return { pressed: 'panel absent after remount', href: null };
  return pressForRow(page, fingerprint);
}

// ------------------------------------------------------------------------ the tier

export async function runTier({ opts, log, channels }) {
  const { api, preview, anonKey, hostBTag } = opts;
  const sql = channels.maintenance;
  const checks = [];
  const check = (group, name, ok, detail = '') => {
    checks.push({ group, name, ok: ok === true, detail: String(detail) });
    log(`[${group}] ${ok === true ? 'ok  ' : 'FAIL'} ${name}${detail === '' ? '' : ` → ${detail}`}`);
    return ok === true;
  };
  const note = (group, text) => log(`[${group}] note: ${text}`);

  // ---- PRELUDE ------------------------------------------------------------------
  const index = await fetch(`${preview}/`);
  const served = await index.text();
  const onDisk = readFileSync(resolve(ROOT, 'dist', 'index.html'), 'utf8');
  check('PRELUDE', 'P-01 the bundle under test is the one this checkout built',
    served === onDisk,
    served === onDisk ? `GET / answered ${index.status} and its index.html is byte-identical to dist/index.html`
      : `GET / answered ${index.status} and the served index differs from dist/index.html `
        + `(${served.length} vs ${onDisk.length} bytes)`);

  const health = await sql.call('/auth/v1/health');
  check('PRELUDE', 'P-02 the local stack answers on the loopback API origin',
    health.status === 200, `GET /auth/v1/health → ${health.status}`);

  const fixture = JSON.parse(readFileSync(opts.fixturePath, 'utf8'));
  const weddingId = fixture.wedding_id;
  if (!UUID.test(weddingId)) throw new Refusal(`refused: ${opts.fixturePath} names no wedding uuid.`);
  const dbRows = await sql.rows(`/rest/v1/invitation_outputs?wedding_id=eq.${weddingId}`
    + '&select=id,output_kind,variant,format,page_number,status,content_digest,storage_domain,'
    + 'object_key,version_id,render_config_hash,attempt_count,created_at'
    + '&order=output_kind,variant,format,page_number');
  const deliverable = dbRows.filter((r) => r.status === 'ready' && r.storage_domain === 'host_private');
  if (deliverable.length === 0) {
    throw new Refusal(`refused: wedding ${weddingId} holds no ready, host-private artefact, so there is `
      + 'nothing for the panel to deliver. Run the publisher for this version first.');
  }
  check('PRELUDE', 'P-03 the fixture wedding holds ready, host-private artefacts with digests',
    deliverable.every((r) => /^[0-9a-f]{64}$/.test(String(r.content_digest))),
    `${dbRows.length} row(s) recorded, ${deliverable.length} ready and private`);
  note('PRELUDE', `fixture version ${fixture.version_id}; artefacts: `
    + deliverable.map((r) => `${r.output_kind}/${r.variant}/${r.format} p${r.page_number}`).join(', '));

  const censusOf = async () => {
    const outputs = await sql.rows('/rest/v1/invitation_outputs?select=id,status');
    const weddings = await sql.rows('/rest/v1/weddings?select=id');
    return {
      outputs: outputs.length,
      ready: outputs.filter((o) => o.status === 'ready').length,
      weddings: weddings.length,
    };
  };
  const censusBefore = await censusOf();
  note('PRELUDE', `census before the run: ${censusBefore.outputs} manifest row(s), `
    + `${censusBefore.ready} ready, ${censusBefore.weddings} wedding(s)`);

  // ---- the host session ---------------------------------------------------------
  const browser = await openBrowser({ cdpPort: opts.cdpPort });
  let b = null;
  try {
    const hostA = await browser.newPage('host-a');
    await signInHost(hostA, preview, {
      email: fixture.email, password: opts.hostAPassword, label: 'the fixture host',
    });
    log('the fixture host reached /dashboard through the shipped form, with no email-confirmation step');

    const rows = await openPanel(hostA, preview, weddingId);
    check('HOST-LIST', 'H-01 the panel mounts for the owner as a labelled region',
      Array.isArray(rows), `${rows.length} row element(s) read from section[aria-labelledby="outputs-heading"]`);

    // Screen and database are compared by the value a host can actually see: the first twelve characters
    // of the digest the publisher verified. A list that agreed with itself but not with the manifest
    // fails here rather than looking like a success.
    const onScreen = rows.filter((r) => r.fingerprint !== null).map((r) => r.fingerprint).sort();
    const fromDb = deliverable.map((r) => r.content_digest.slice(0, 12)).sort();
    check('HOST-LIST', 'H-02 every recorded artefact appears, and nothing else does',
      onScreen.length === fromDb.length && onScreen.every((f, i) => f === fromDb[i]),
      `${onScreen.length} fingerprint(s) on screen vs ${fromDb.length} row(s) in the manifest`);

    const headings = await hostA.evaluate(`(() => {
      const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
      return [...s.querySelectorAll('h3')].map((h) => h.textContent.trim());
    })()`);
    const firstWords = [...new Set(deliverable.map((r) => r.output_kind))];
    const labelFor = { og_image: 'Link preview', share_image: 'Share images', pdf: 'Print-ready PDF', qr: 'QR plates' };
    const expected = firstWords.map((k) => labelFor[k] ?? `this build has no word for the kind “${k}”`);
    check('HOST-LIST', 'H-03 each kind the manifest holds gets its own group heading',
      expected.every((h) => headings.includes(h)) && headings.length === expected.length,
      `headings ${JSON.stringify(headings)} for ${JSON.stringify(expected)}`);

    const bodyA = (await hostA.bodyText()).replace(/\s+/g, ' ');
    // The sentence the panel actually writes (InvitationOutputsPanel.tsx:216-220) is
    // "N files are recorded for this wedding, M of them openable right now." — the second number
    // stands before "of", not after it. Both numbers are then compared with the manifest.
    const tallyMatch = /(\d+) (?:file is|files are) recorded for this wedding, (\d+) of (?:it openable|them openable) right now/.exec(bodyA);
    check('HOST-LIST', 'H-04 the tally sentence reports the manifest rather than a fixed number',
      tallyMatch !== null && Number(tallyMatch[1]) === dbRows.length && Number(tallyMatch[2]) === deliverable.length,
      tallyMatch === null ? `no tally sentence on the page; said: ${bodyA.slice(0, 160)}`
        : `${tallyMatch[1]} recorded, ${tallyMatch[2]} openable against ${dbRows.length}/${deliverable.length} in the manifest`);

    const statuses = await hostA.evaluate(`(() => {
      const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
      return [...s.querySelectorAll('li')]
        .filter((li) => li.closest('[role="status"]') === null)
        .map((li) => (/Ready to open\\./.test(li.innerText) ? 'ready' : 'other'));
    })()`);
    check('HOST-LIST', 'H-05 every row says it is ready, which is what its status claims',
      statuses.length === deliverable.length && statuses.every((x) => x === 'ready'),
      `${statuses.length} row(s), ${statuses.filter((x) => x === 'ready').length} saying "Ready to open."`);

    // What the panel says *besides* the rows is decided by reprintWarnings() in
    // src/lib/invitationOutputs.ts:272-313: a sentence per retired-row reason, plus one fixed
    // sentence whenever a ready QR plate exists, because the projection deliberately carries no
    // target-url digest for this read to compare against. On this manifest the first family must be
    // silent (nothing is invalidated) and the second must be present. A check that merely counted
    // live regions would have called the honest sentence a defect and the product would have been
    // "repaired" into a lie.
    const noticeList = await hostA.evaluate(`(() => {
      const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
      return [...s.querySelectorAll('[role="status"] li')].map((li) => li.innerText.trim().replace(/\\s+/g, ' '));
    })()`);
    const retiredSentences = noticeList.filter((text) => /retired|reprint|print again from the new/i.test(text)
      && !text.startsWith('A QR plate is a promise about an address'));
    const limitSentence = noticeList.find((text) => text.startsWith('A QR plate is a promise about an address'));
    const qrReady = deliverable.filter((r) => r.output_kind === 'qr' && r.status === 'ready').length;
    check('HOST-LIST', 'H-06 an all-ready manifest draws no reprint warning, only the sentence about what this list cannot see',
      dbRows.every((r) => r.status === 'ready') && retiredSentences.length === 0
      && noticeList.length === (qrReady > 0 ? 1 : 0) && (qrReady > 0) === (limitSentence !== undefined),
      `${noticeList.length} notice(s) with ${dbRows.filter((r) => r.status === 'invalidated').length} `
      + `invalidated row(s) and ${qrReady} ready QR plate(s); ${retiredSentences.length} of them name a `
      + 'retirement'
      + (limitSentence === undefined ? '; the limit sentence is absent'
        : `; the limit sentence reads "${limitSentence.slice(0, 72)}…"`));

    // ---- DELIVERY ---------------------------------------------------------------
    const drift = deliverable.filter((r) => composedPath(weddingId, r) !== r.object_key);
    check('DELIVERY', 'D-P01 the path the client composes is the key the database minted',
      drift.length === 0,
      drift.length === 0 ? `all ${deliverable.length} composed path(s) equal their row's object_key`
        : `${drift.length} row(s) differ, e.g. ${drift[0].id}: composed ${composedPath(weddingId, drift[0])} `
          + `vs stored ${drift[0].object_key}`);

    const delivered = [];
    for (const row of deliverable) {
      const fingerprint = row.content_digest.slice(0, 12);
      const { pressed, href, said } = await pressForRow(hostA, fingerprint);
      const id = `D-${row.output_kind}-${row.variant}-${row.format}-p${row.page_number}`;
      if (typeof href !== 'string') {
        check('DELIVERY', `${id} the panel mints a link for this row`, false,
          `press answered ${pressed}${said ? `; the row said: ${said}` : ''}`);
        continue;
      }
      const url = new URL(href);
      // `createSignedUrl` answers `/storage/v1/object/sign/{bucket}/{key}`, so the bucket is part of
      // the address in front of the key the manifest holds. The name is the product's own constant
      // (`BUCKET` at src/integrations/supabase/invitationOutputs.ts:49), which that module keeps
      // private; repeating it here is the price of checking the shape instead of the download alone.
      const expectedPath = `/storage/v1/object/sign/${OUTPUT_BUCKET}/${row.object_key}`;
      const shapeOk = url.pathname === expectedPath
        && url.hostname === new URL(api).hostname
        && url.searchParams.get('token') !== null;
      const got = await download(href);
      const digest = createHash('sha256').update(got.buffer).digest('hex');
      const tests = MAGIC[row.format] ?? [];
      const magic = tests.length === 0
        ? false
        : tests.some((t) => (typeof t === 'function' ? t(got.buffer) : got.buffer.subarray(0, t.length).equals(t)));
      const ok = check('DELIVERY', `${id} the bytes behind the link hash to the recorded digest`,
        got.status === 200 && digest === row.content_digest && got.bytes > 0 && magic && shapeOk,
        `HTTP ${got.status}, ${got.bytes} bytes, served as ${got.contentType}; sha256 ${digest.slice(0, 16)}… `
        + `${digest === row.content_digest ? '==' : '!='} the row's digest; address `
        + `${shapeOk ? 'is the signed private path for that key' : `not as expected (${url.pathname})`}`);
      delivered.push({ id, row, href, ok });
    }

    // The TTL promise is measured, not read off the constant: one address is fetched again after its own
    // window has closed, and a second address for the same row is minted afterwards — which shows the
    // object is alive and it was the *address* that died.
    const sample = delivered.find((d) => d.ok) ?? delivered[0];
    if (sample) {
      const claim = expiryOf(sample.href);
      const window = claim === null ? null : Math.round((claim.expMs - Date.now()) / 1000);
      const readable = claim !== null && window >= 30 && window <= 120;
      check('DELIVERY', 'D-TTL-01 the minted address says when it dies, and the window is short',
        readable, claim === null
          ? 'no expiry readable in the address, so the empirical test below carries the claim'
          : `${window}s from now, read from the ${claim.source}`);
      if (readable) {
        const waitMs = Math.max(0, claim.expMs - Date.now()) + 8_000;
        log(`waiting ${Math.round(waitMs / 1000)}s, past the address's own expiry`);
        await sleep(waitMs);
        const after = await download(sample.href);
        // The refusal has to name the token, or "not 200" would equally be a dead object, a stopped
        // Storage service or a 500. Its body is checked, and the fresh address below is the control that
        // shows the bytes were still there.
        const said = after.buffer.toString('utf8').slice(0, 200);
        // Measured on this stack, the answer at HTTP 400 is
        // `{"statusCode":"400","error":"InvalidJWT","message":"\"exp\" claim timestamp check failed"}` —
        // words an invented pattern had missed. The case still requires the refusal to speak about the
        // token's window, so a body naming a missing object or a stopped service would not pass at any
        // status, and the fresh address below remains the control that the bytes were still there.
        const lower = said.toLowerCase();
        const saysExpiry = ['invalidjwt', 'expire', '"exp"', 'invalid token', 'jwt']
          .some((marker) => lower.includes(marker));
        const saysLostObject = ['nosuchkey', 'not found', 'nosuchbucket', 'bucket not found']
          .some((marker) => lower.includes(marker));
        check('DELIVERY', 'D-TTL-02 that address is refused once its window has passed, and says why',
          after.status !== 200 && saysExpiry && !saysLostObject,
          `HTTP ${after.status}, ${after.bytes} bytes, content-type ${String(after.contentType).slice(0, 40)}; `
          + `body ${said}`);
        const again = await pressAfterRemount(hostA, preview, weddingId, sample.row.content_digest.slice(0, 12));
        const fresh = again.href === null ? null : await download(again.href);
        check('DELIVERY', 'D-TTL-03 a freshly minted address for the same row works again',
          fresh !== null && fresh.status === 200
          && createHash('sha256').update(fresh.buffer).digest('hex') === sample.row.content_digest,
          fresh === null ? `the panel offered no second address (press answered ${again.pressed})`
            : `HTTP ${fresh.status}, ${fresh.bytes} bytes, digest `
              + `${createHash('sha256').update(fresh.buffer).digest('hex') === sample.row.content_digest
                ? 'matched' : 'did NOT match'} (so the refusal above was expiry, not a lost object)`);
      } else {
        check('DELIVERY', 'D-TTL-02 that address is refused once its window has passed', false,
          'the window was never measured, so there was no deadline to cross');
        check('DELIVERY', 'D-TTL-03 a freshly minted address for the same row works again', false,
          'not attempted: waiting for an unstated deadline proves nothing');
      }

      // A signed address is a temporary credential, so the panel's contract is that it is never printed
      // as copyable text and never persisted anywhere a later page could pick it up. Both are read from
      // the page rather than asserted about the component.
      const leak = await hostA.evaluate(`(() => {
        const stored = [];
        for (const [key, value] of Object.entries(window.localStorage)) {
          if (/token=|sign\\/invitation-outputs/.test(String(value))) stored.push(key);
        }
        return { inText: /token=/.test(document.body.innerText), stored };
      })()`);
      check('DELIVERY', 'D-HY-01 no signed address appears as text a host could copy out of the page',
        leak.inText === false, leak.inText
          ? 'a `token=` string is present in the page text'
          : 'each address exists only as an anchor href');
      check('DELIVERY', 'D-HY-02 no signed address is written to localStorage',
        leak.stored.length === 0, leak.stored.length === 0
          ? 'nothing signed is persisted'
          : `key(s) holding a signed address: ${leak.stored.join(', ')}`);
    } else {
      for (const name of ['D-TTL-01', 'D-TTL-02', 'D-TTL-03']) {
        check('DELIVERY', name, false, 'no artefact produced a link, so no window was ever minted');
      }
    }

    // ---- REFUSAL: an anonymous visitor -------------------------------------------
    const oneKey = deliverable[0].object_key;
    const anonPage = await browser.newPage('anonymous');
    await anonPage.goto(`${preview}/project/${weddingId}/edit`);
    await sleep(1_500);
    const anonMounted = await anonPage.evaluate(`(() => Boolean(document.querySelector(`
      + `'section[aria-labelledby="outputs-heading"]')))()`);
    const anonText = (await anonPage.bodyText()).replace(/\s+/g, ' ');
    check('REFUSAL', 'R-A1 an anonymous visitor is not shown the host panel',
      anonMounted === false && !/Ready to open\./.test(anonText),
      `mounted=${anonMounted} at ${(await anonPage.currentUrl()).replace(preview, '<preview>')}; `
      + `said: ${anonText.slice(0, 140)}`);

    const anonHeaders = { apikey: anonKey, 'Content-Type': 'application/json', Authorization: `Bearer ${anonKey}` };
    const manifestCall = await discoverManifestCall(hostA);
    const anonRpc = await anonPage.fetchFromPage(manifestCall.url, {
      method: 'POST',
      headers: { ...anonHeaders, ...(manifestCall.profile === null ? {} : { 'Content-Profile': manifestCall.profile }) },
      body: JSON.stringify({ p_wedding_id: weddingId }) });
    const anonRows = (() => { try { const j = JSON.parse(anonRpc.text); return Array.isArray(j) ? j.length : null; } catch { return null; } })();
    check('REFUSAL', 'R-A2 an anonymous manifest read gives out no artefacts',
      anonRpc.status !== 200 && refusalResolves(anonRpc.text) && (anonRows === null || anonRows === 0),
      `HTTP ${anonRpc.status}; ${anonRows === null ? 'no row list in the reply' : `${anonRows} row(s)`}; `
      + `body ${anonRpc.text.slice(0, 140)}`);

    const anonSign = await anonPage.fetchFromPage(`${api}/storage/v1/object/sign/${OUTPUT_BUCKET}/${oneKey}`, {
      method: 'POST', headers: anonHeaders, body: JSON.stringify({ expiresIn: 60 }) });
    check('REFUSAL', 'R-A3 an anonymous session cannot mint a signed URL for a private object',
      anonSign.status !== 200 && /signedURL|signedUrl/.test(anonSign.text) === false
      && refusalResolves(anonSign.text),
      `HTTP ${anonSign.status}; body ${anonSign.text.slice(0, 140)}`);

    const anonDirect = await anonPage.fetchFromPage(`${api}/storage/v1/object/${OUTPUT_BUCKET}/${oneKey}`,
      { method: 'GET', headers: { apikey: anonKey, Authorization: `Bearer ${anonKey}` } });
    check('REFUSAL', 'R-A4 an anonymous direct object read is refused',
      anonDirect.status !== 200 && refusalResolves(anonDirect.text),
      `HTTP ${anonDirect.status}; ${anonDirect.text.slice(0, 120)}`);

    // `Bucket not found` is the answer a private bucket gives to the public route, and that answer is
    // the property being claimed here rather than a bad address — so this case does not run the
    // malformed-address filter. The address itself is proven to resolve because the owner downloads from
    // it (the D- cases above) and because the two refusals directly above name this bucket correctly.
    const anonPublic = await anonPage.fetchFromPage(`${api}/storage/v1/object/public/${OUTPUT_BUCKET}/${oneKey}`,
      { method: 'GET', headers: { apikey: anonKey } });
    check('REFUSAL', 'R-A5 the outputs bucket is private, so its objects have no unauthenticated path',
      anonPublic.status !== 200 && /RIFF|%PDF-|PNG/.test(anonPublic.text) === false,
      `HTTP ${anonPublic.status}; ${anonPublic.text.length} byte(s) of reply; `
      + `body ${anonPublic.text.slice(0, 120)}`);

    // ---- REFUSAL: another wedding's owner ----------------------------------------
    const hostBEmail = `${HOST_B_PREFIX}+${hostBTag}@example.test`;
    const hostBPassword = `local-only-${hostBTag}`;
    b = await signUpSecondHost(browser, preview, {
      email: hostBEmail, password: hostBPassword, weddingTitle: `delivery tier ${hostBTag}`,
    });
    log(`the second host signed up through the shipped form and owns wedding ${b.weddingId}`);

    const bRows = await openPanel(b.page, preview, b.weddingId);
    const bText = (await b.page.bodyText()).replace(/\s+/g, ' ');
    check('REFUSAL', 'R-B1 another wedding\'s owner sees their own empty manifest',
      bRows.length === 0 && /Nothing has been rendered for this invitation yet/.test(bText),
      `${bRows.length} row(s) in their panel; ${/cannot start a render/.test(bText)
        ? 'the empty state names the worker rather than offering a render button'
        : 'the empty state did not say what it should'}`);

    await b.page.goto(`${preview}/project/${weddingId}/edit`);
    await sleep(1_500);
    const bOnA = (await b.page.bodyText()).replace(/\s+/g, ' ');
    const seesRows = deliverable.filter((r) => bOnA.includes(r.content_digest.slice(0, 12)));
    check('REFUSAL', 'R-B2 that host is shown none of the first wedding\'s files in the app',
      seesRows.length === 0,
      `${seesRows.length} of ${deliverable.length} fingerprint(s) visible at `
      + `${(await b.page.currentUrl()).replace(preview, '<preview>')}; said: ${bOnA.slice(0, 160)}`);

    const bToken = await b.page.authHeader();
    if (bToken === null) throw new Refusal('refused: the second host\'s own session token could not be read.');
    const bHeaders = { apikey: anonKey, 'Content-Type': 'application/json', Authorization: `Bearer ${bToken}` };
    const bRpc = await b.page.fetchFromPage(manifestCall.url, {
      method: 'POST',
      headers: { ...bHeaders, ...(manifestCall.profile === null ? {} : { 'Content-Profile': manifestCall.profile }) },
      body: JSON.stringify({ p_wedding_id: weddingId }) });
    const bRows2 = (() => { try { const j = JSON.parse(bRpc.text); return Array.isArray(j) ? j.length : null; } catch { return null; } })();
    check('REFUSAL', 'R-B3 the manifest RPC refuses a non-owner rather than answering an empty list',
      bRpc.status !== 200 && refusalResolves(bRpc.text)
      && (bRows2 === null || bRows2 === 0),
      `HTTP ${bRpc.status}; ${bRows2 === null ? 'no row list in the reply' : `${bRows2} row(s)`}; `
      + `body ${bRpc.text.slice(0, 160)}`);

    // Bucket-qualified exactly as the owner's own mint is (`:709`), because an address that names no
    // object answers with `NoSuchBucket` for anybody at all. That was the shape this case had before, so
    // its pass said nothing about ownership; the same filter the anonymous half uses applies here.
    const bSign = await b.page.fetchFromPage(`${api}/storage/v1/object/sign/${OUTPUT_BUCKET}/${oneKey}`, {
      method: 'POST', headers: bHeaders, body: JSON.stringify({ expiresIn: 60 }) });
    check('REFUSAL', 'R-B4 a non-owner cannot mint a signed URL for that object',
      bSign.status >= 400 && refusalResolves(bSign.text) && /signedUrl/.test(bSign.text) === false,
      `HTTP ${bSign.status}; body ${bSign.text.slice(0, 140)}`);

    const bDirect = await b.page.fetchFromPage(`${api}/storage/v1/object/${OUTPUT_BUCKET}/${oneKey}`, {
      method: 'GET', headers: { apikey: anonKey, Authorization: `Bearer ${bToken}` } });
    check('REFUSAL', 'R-B5 a non-owner\'s direct read of that object is refused',
      bDirect.status !== 200 && refusalResolves(bDirect.text),
      `HTTP ${bDirect.status}; ${bDirect.text.slice(0, 120)}`);

    // The same object still delivering to its owner is what turns the refusals above into evidence about
    // ownership rather than about a stopped Storage service or a bucket that lost its bytes.
    const aliveRow = delivered.find((d) => d.row.id !== sample?.row.id)?.row ?? deliverable[0];
    const alivePress = await pressAfterRemount(hostA, preview, weddingId, aliveRow.content_digest.slice(0, 12));
    const alive = alivePress.href === null ? null : await download(alivePress.href);
    check('REFUSAL', 'R-X1 the owner still gets bytes afterwards, so the refusals were about the caller',
      alive !== null && alive.status === 200 && alive.bytes > 0,
      alive === null ? `the panel offered no link (press answered ${alivePress.pressed})`
        : `HTTP ${alive.status}, ${alive.bytes} bytes for ${aliveRow.output_kind}/${aliveRow.variant}`);

    // ---- A11Y ---------------------------------------------------------------------
    await hostA.goto(`${preview}/project/${weddingId}/edit`);
    await openPanel(hostA, preview, weddingId);
    const controls = await hostA.evaluate(PANEL_CONTROLS);
    const small = controls.filter((c) => !c.disabled && (c.height < 44 || c.width < 44));
    check('A11Y', 'A-01 every actionable control in the panel is at least 44 px on both axes',
      controls.length > 0 && small.length === 0,
      `${controls.length} control(s) measured, ${small.length === 0 ? 'all ≥44 px'
        : `too small: ${small.map((c) => `${c.name || c.tag} ${c.width}×${c.height}`).join(' | ')}`}`);
    const unnamed = controls.filter((c) => c.name === '');
    check('A11Y', 'A-02 every control announces a name of its own',
      unnamed.length === 0,
      unnamed.length === 0 ? 'all named by their text' : `${unnamed.length} unnamed control(s)`);
    const untouchable = controls.filter((c) => !c.tabbable);
    check('A11Y', 'A-03 every control is reachable from the keyboard',
      untouchable.length === 0,
      `${controls.length - untouchable.length}/${controls.length} with a non-negative tabIndex`);
    const contrast = await hostA.evaluate(PANEL_CONTRAST);
    const failing = contrast.filter((c) => c.ratio < c.required);
    const worst = contrast.reduce((m, c) => (m === null || c.ratio < m.ratio ? c : m), null);
    check('A11Y', 'A-04 panel text meets the WCAG contrast minimum for its size',
      contrast.length > 0 && failing.length === 0,
      `${contrast.length} text node(s), lowest ${worst.ratio}:1 on “${worst.text}” at ${worst.size}px `
      + `(needs ${worst.required}:1); ${failing.length} below the minimum`);
    // The editor embeds the guest document in its preview column, and that document carries its own
    // level-1 heading by design — the same carve-out `scripts/stage5-a11y-mobile.mjs:226-229` makes and
    // Stage 8's guest journey relies on. A blanket page count would report that documented shape as a
    // defect, so the two scopes are counted apart here rather than the finding being dropped.
    const structure = await hostA.evaluate(`(() => {
      const inPreview = (el) => el.closest('[aria-labelledby="preview-heading"],[aria-label="Preview"]') !== null;
      const all = [...document.querySelectorAll('h1')];
      const panel = document.querySelector('section[aria-labelledby="outputs-heading"]');
      const levels = panel
        ? [...panel.querySelectorAll('h1,h2,h3,h4,h5,h6')].map((h) => Number(h.tagName.slice(1)))
        : [];
      const skips = [];
      for (let i = 1; i < levels.length; i += 1) {
        if (levels[i] - levels[i - 1] > 1) skips.push(levels[i - 1] + '\\u2192' + levels[i]);
      }
      return {
        chromeH1: all.filter((h) => !inPreview(h)).length,
        previewH1: all.filter(inPreview).length,
        headingTag: panel ? (panel.querySelector('#outputs-heading')?.tagName ?? 'absent') : 'absent',
        labelled: panel !== null,
        levels, skips,
      };
    })()`);
    check('A11Y', 'A-05 the panel is a labelled region under one page title, with no skipped heading level',
      structure.labelled && structure.chromeH1 === 1 && structure.headingTag === 'H2'
      && structure.skips.length === 0,
      `page-chrome h1 ${structure.chromeH1}, preview-document h1 ${structure.previewH1}, panel heading `
      + `<${structure.headingTag}>, aria-labelledby resolves: ${structure.labelled}; panel levels `
      + `[${structure.levels.join(',')}]`
      + (structure.skips.length === 0 ? ', no level skipped' : `, skipped at ${structure.skips.join(', ')}`));
    await hostA.evaluate(`(() => { document.querySelector('#outputs-heading')`
      + `.scrollIntoView({ block: 'center' }); return 1; })()`);
    let focused = null;
    for (let i = 0; i < 40 && focused === null; i += 1) {
      await hostA.pressTab();
      const inside = await hostA.evaluate(`(() => {
        const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
        return s ? s.contains(document.activeElement) : false;
      })()`);
      if (inside === true) focused = await hostA.focusInfo();
    }
    const visibleRing = focused !== null
      && (((parseFloat(focused.outlineWidth) || 0) > 0 && focused.outlineStyle !== 'none')
        || String(focused.boxShadow) !== 'none');
    check('A11Y', 'A-06 a keyboard user can stop inside the panel and sees an indicator',
      visibleRing, focused === null ? 'Tab never landed inside the panel within 40 stops'
        : `stopped on “${focused.label}” (${focused.width}×${focused.height}) with outline `
          + `${focused.outlineStyle} ${focused.outlineWidth} and ring ${String(focused.boxShadow).slice(0, 60)}`);
    const amber = (await hostA.evaluate(WARNING_CONTRAST)) ?? [];
    const amberFailing = amber.filter((c) => c.ratio < c.required);
    const amberWorst = amber.reduce((m, c) => (m === null || c.ratio < m.ratio ? c : m), null);
    check('A11Y', 'A-07 every warning-coloured sentence on the page clears the contrast minimum',
      amber.length > 0 && amberFailing.length === 0,
      amber.length === 0
        ? 'no visible .text-warning run outside the preview, so this sweep measured nothing and proves nothing'
        : `${amber.length} run(s) drawn from --warning, lowest ${amberWorst.ratio}:1 on “${amberWorst.text}” `
          + `in “${amberWorst.label}” at ${amberWorst.size}px (needs ${amberWorst.required}:1); `
          + `${amberFailing.length} below the minimum`);

    // ---- MOBILE -------------------------------------------------------------------
    await hostA.setViewportSizeOnly({ width: 390, height: 844, dpr: 2, mobile: true });
    await sleep(600);
    const mobile = await hostA.evaluate(`(() => {
      const s = document.querySelector('section[aria-labelledby="outputs-heading"]');
      const r = s.getBoundingClientRect();
      return {
        overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        panelRight: Math.round(r.right), viewport: window.innerWidth,
        controls: [...s.querySelectorAll('button,a[href]')]
          .map((el) => { const b = el.getBoundingClientRect(); return {
            name: (el.textContent || '').trim().slice(0, 26),
            width: Math.round(b.width), height: Math.round(b.height) }; })
          .filter((c) => c.height > 0),
      };
    })()`);
    check('MOBILE', 'M-01 at 390×844 nothing overflows the viewport horizontally',
      mobile.overflow <= 0 && mobile.panelRight <= mobile.viewport + 1,
      `document overflow ${mobile.overflow} px; panel right edge ${mobile.panelRight} in a `
      + `${mobile.viewport} px viewport`);
    const mobileSmall = mobile.controls.filter((c) => c.height < 44 || c.width < 44);
    check('MOBILE', 'M-02 the same affordances are still tappable at that width',
      mobile.controls.length > 0 && mobileSmall.length === 0,
      `${mobile.controls.length} control(s) at mobile width, ${mobileSmall.length === 0 ? 'all ≥44 px'
        : `too small: ${mobileSmall.map((c) => `${c.name} ${c.width}×${c.height}`).join(' | ')}`}`);

    // ---- NETWORK: nothing left this machine ----------------------------------------
    const traffic = [...await hostA.networkLog(), ...await anonPage.networkLog(), ...await b.page.networkLog()];
    // Sorted by what the address *is* rather than by a hostname guess. The last run printed
    // `host(s): 127.0.0.1, ` — an empty hostname, which is a `data:`/`blob:` address, i.e. bytes that
    // were inline in the document and never had a peer to reach. Calling that "external" was a false
    // failure; a filter that quietly ignored it instead would have made an unreadable address free.
    const addressed = traffic.map((r) => {
      try {
        const url = new URL(r.url);
        // Origin and path, never the query: a signed delivery address carries its credential there, and a
        // failure detail must not become the one place a token gets written down.
        return { host: url.hostname, scheme: url.protocol.replace(/:/g, ''), name: `${url.host}${url.pathname}` };
      } catch {
        return { host: null, scheme: 'unparseable', name: String(r.url).slice(0, 80) };
      }
    });
    const loopback = [...new Set(addressed.filter((a) => LOOPBACK.has(a.host)).map((a) => a.host))];
    const inline = [...new Set(addressed.filter((a) => a.host === '').map((a) => a.scheme))];
    const offenders = addressed.filter((a) => a.host === null || !(LOOPBACK.has(a.host) || a.host === ''));
    check('NETWORK', 'N-01 every request the three sessions made went to a loopback host',
      traffic.length > 0 && offenders.length === 0,
      `${traffic.length} request(s): loopback ${loopback.join(', ') || 'none'}; inline (no peer) `
      + `${inline.join(', ') || 'none'}; ${offenders.length === 0 ? 'nothing else'
        : `elsewhere: ${offenders.slice(0, 5).map((o) => `${o.scheme}://${o.name}`).join(' | ')}`}`);
    const headerText = makeRedactor([])(traffic.map((r) => JSON.stringify(r.headers ?? {})).join(' '));
    check('NETWORK', 'N-02 the service-role key appears in no captured request header',
      headerText.includes(opts.serviceKey) === false,
      `${traffic.length} request(s) searched for the privileged key`);
    const pageSecrets = await hostA.evaluate(`(() => {
      const all = Object.entries(window.localStorage).map(([k, v]) => k + ':' + v).join(' ') + ' ' + document.cookie;
      return { hasPrivilegedWord: /service_role|service-role/i.test(all), bytes: all.length };
    })()`);
    check('NETWORK', 'N-03 the browser\'s own persisted state holds no privileged-role marker',
      pageSecrets.hasPrivilegedWord === false,
      `${pageSecrets.bytes} byte(s) of session state read back through the page`);

    // ---- TEARDOWN ------------------------------------------------------------------
    if (opts.keepSecondHost) {
      note('TEARDOWN', `--keep-second-host: wedding ${b.weddingId} and ${hostBEmail} were left in place`);
    } else {
      const wedDel = await sql.call(`/rest/v1/weddings?id=eq.${b.weddingId}`, { method: 'DELETE' });
      const gone = await sql.rows(`/rest/v1/weddings?id=eq.${b.weddingId}&select=id`);
      check('TEARDOWN', 'T-01 the second wedding this run created is deleted',
        wedDel.status === 204 && gone.length === 0,
        `DELETE → ${wedDel.status}; ${gone.length} row(s) left under that id`);
      const directory = await sql.call('/auth/v1/admin/users?page=1&per_page=1000');
      const accounts = (directory.json?.users ?? []).filter((u) => String(u.email).startsWith(`${HOST_B_PREFIX}+`));
      let removed = 0;
      for (const u of accounts) {
        const r = await sql.call(`/auth/v1/admin/users/${u.id}`, { method: 'DELETE' });
        if (r.status === 200) removed += 1;
      }
      const relogin = await fetch(`${api}/auth/v1/token?grant_type=password`, {
        method: 'POST',
        headers: { apikey: anonKey, 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: hostBEmail, password: hostBPassword }),
      });
      check('TEARDOWN', 'T-02 every account this tier signed up is removed and can no longer sign in',
        accounts.length > 0 && removed === accounts.length && relogin.status >= 400,
        `${removed}/${accounts.length} account(s) with the ${HOST_B_PREFIX}+ prefix deleted; the run's own `
        + `address answers re-login HTTP ${relogin.status}`);
      const censusAfter = await censusOf();
      check('TEARDOWN', 'T-03 the census is exactly where the run found it',
        censusAfter.outputs === censusBefore.outputs && censusAfter.ready === censusBefore.ready
        && censusAfter.weddings === censusBefore.weddings,
        `before ${censusBefore.outputs}/${censusBefore.ready}/${censusBefore.weddings}, after `
        + `${censusAfter.outputs}/${censusAfter.ready}/${censusAfter.weddings} `
        + '(manifest rows / ready rows / weddings)');
      const ownerStill = await sql.rows(`/rest/v1/invitation_outputs?wedding_id=eq.${weddingId}&select=id,status`);
      check('TEARDOWN', 'T-04 the fixture wedding and its artefacts are untouched by the refusals',
        ownerStill.length === dbRows.length && ownerStill.every((r) => r.status === 'ready'),
        `${ownerStill.length} row(s) still recorded for ${weddingId.slice(0, 8)}, `
        + `${ownerStill.filter((r) => r.status === 'ready').length} of them ready`);
    }
  } finally {
    const closed = await browser.close()
      .catch((error) => ({ profileRemoved: false, reason: String(error?.message ?? error) }));
    log(`browser closed: profileRemoved=${closed.profileRemoved}`
      + (closed.profilePath ? ` profile=${closed.profilePath}` : '')
      + (closed.reason ? ` reason=${closed.reason}` : ''));
    // Measured, then decided. On Windows the handle on a profile directory is routinely still held for a
    // moment after the last browser process exits, so the driver's single unlink answers EPERM for a
    // directory that deletes cleanly seconds later — proven this session, where the run's own profile
    // removed on the first try once the wait was over. So the verdict is the product of a bounded retry
    // on exactly the path the driver reported (never a glob, never another directory) plus a read-back of
    // whether the directory still exists — not whether one unlink call happened to land.
    const target = typeof closed.profilePath === 'string' ? closed.profilePath : null;
    let reason = closed.reason ?? null;
    for (let i = 0; target !== null && existsSync(target) && i < 8; i += 1) {
      await sleep(1_500);
      try {
        rmSync(target, { recursive: true, force: true });
      } catch (error) {
        reason = String(error?.message ?? error);
      }
    }
    const gone = target === null ? closed.profileRemoved === true : existsSync(target) === false;
    check('TEARDOWN', 'T-05 the Chromium profile that held the host sessions is deleted',
      gone === true,
      target === null ? `the driver reported no profile path; its own answer was ${closed.profileRemoved}`
        : `${target} exists: ${existsSync(target)}`
          + (reason === null ? '' : `; last removal error ${String(reason).slice(0, 120)}`));
  }

  return { checks, censusBefore };
}

// ------------------------------------------------------------------------ CLI

export async function mainCli({ argv = process.argv.slice(2), env = process.env, stdout = process.stdout } = {}) {
  let opts;
  try {
    opts = readOptions(parseArgs(argv), env);
  } catch (error) {
    stdout.write(`${error.message}\n`);
    return error instanceof Refusal ? error.exitCode : 2;
  }
  const redact = makeRedactor([opts.serviceKey, opts.anonKey, opts.hostAPassword]);
  const log = (line) => stdout.write(`${redact(line)}\n`);
  mkdirSync(opts.evidenceDir, { recursive: true });

  const started = new Date().toISOString();
  let result;
  try {
    result = await runTier({
      opts, log,
      channels: { maintenance: makeMaintenance({ api: opts.api, serviceKey: opts.serviceKey, anonKey: opts.anonKey }) },
    });
  } catch (error) {
    log(`refused or failed: ${redact(String(error?.message ?? error)).slice(0, 500)}`);
    return error instanceof Refusal ? error.exitCode : 1;
  }

  const groups = {};
  for (const c of result.checks) {
    groups[c.group] = groups[c.group] ?? { pass: 0, fail: 0 };
    groups[c.group][c.ok ? 'pass' : 'fail'] += 1;
  }
  const failures = result.checks.filter((c) => !c.ok);
  const record = {
    run: 'stage9-browser-outputs',
    started,
    finished: new Date().toISOString(),
    preview_origin: opts.preview,
    api_origin: opts.api,
    fixture_path: opts.fixturePath,
    groups,
    checks: result.checks,
    failures: failures.map((c) => `${c.group}: ${c.name} → ${c.detail}`),
  };
  const file = join(opts.evidenceDir, `browser-outputs-${started.replace(/[:.]/g, '-')}.json`);
  writeFileSync(file, redact(JSON.stringify(record, null, 2)));
  log(`groups: ${Object.entries(groups).map(([g, v]) => `${g} ${v.pass}/${v.pass + v.fail}`).join(', ')}`);
  log(`summary: ${result.checks.length - failures.length}/${result.checks.length} case(s) passed`);
  log(`run record: ${file}`);
  log(failures.length === 0 ? 'RESULT: PASS' : `RESULT: FAIL (${failures.length} case(s))`);
  return failures.length === 0 ? 0 : 1;
}

const invokedDirectly = process.argv[1] !== undefined
  && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  try {
    process.exitCode = await mainCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Refusal ? 'REFUSED' : 'ERROR'}: ${error.message}\n`);
    process.exitCode = error.exitCode ?? 1;
  }
}
